"""Local blind same-reply quality-rating interface."""

RATING_DASHBOARD_HTML = r"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reply quality review desk</title><link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'%3E%3Crect width='32' height='32' rx='4' fill='%2317212b'/%3E%3Cpath d='M8 9h16v3H8zm0 6h16v3H8zm0 6h10v3H8z' fill='%23fff'/%3E%3C/svg%3E"><style>
:root{--canvas:#eef1f4;--paper:#fff;--ink:#17212b;--muted:#687482;--line:#d4dae1;--blue:#245a91;--soft:#eaf1f8;--danger:#9e3939;--body:"Segoe UI",Arial,sans-serif;--record:Georgia,"Times New Roman",serif;--mono:"Cascadia Code",Consolas,monospace}*{box-sizing:border-box}body{margin:0;background:var(--canvas);color:var(--ink);font-family:var(--body)}button,input,select,textarea{font:inherit}:focus-visible{outline:3px solid #245a9133;outline-offset:2px}header{background:#17212b;color:#fff;border-bottom:4px solid var(--blue)}.head{max-width:1180px;margin:auto;padding:18px 28px;display:flex;justify-content:space-between;align-items:center;gap:20px}.head h1{font:600 20px var(--record);margin:0}.head p{margin:4px 0 0;color:#c8d0d8;font-size:12px}.head a{color:#dbe9f7;font-size:12px}.reviewer{display:flex;align-items:center;gap:8px}.reviewer label{font-size:11px;color:#c8d0d8}.reviewer input{width:170px;padding:8px 10px;border:1px solid #52606d;border-radius:4px}main{max-width:1180px;margin:22px auto;padding:0 28px 50px}.progress{display:grid;grid-template-columns:auto 1fr auto;gap:14px;align-items:center;margin-bottom:16px;font:600 12px var(--mono)}.track{height:7px;background:#dce1e7}.fill{height:100%;width:0;background:var(--blue)}.desk{display:grid;grid-template-columns:minmax(0,1fr) 410px;background:var(--paper);border:1px solid var(--line);border-radius:6px;overflow:hidden}.record{padding:30px;border-right:1px solid var(--line)}.number{font:700 11px var(--mono);color:var(--blue);letter-spacing:.06em;text-transform:uppercase}.record h2{font:600 25px var(--record);margin:9px 0 25px}.message{padding:16px;border-left:3px solid var(--line);margin:0 0 18px;background:#fafbfc}.message.reply{border-color:var(--blue);background:var(--soft)}.label{font-size:10px;font-weight:750;letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}.message p{font-size:15px;line-height:1.55;margin:7px 0 0}.act{font:600 12px var(--mono);color:var(--blue)}.note{margin-top:25px;padding-top:15px;border-top:1px solid var(--line);font-size:11px;line-height:1.5;color:var(--muted)}form{padding:25px;background:#fafbfc}.dimension{margin-bottom:18px}.dimension header{display:flex;justify-content:space-between;background:none;color:var(--ink);border:0;margin-bottom:7px}.dimension strong{font-size:12px}.dimension span{font-size:10px;color:var(--muted)}.scale{display:grid;grid-template-columns:repeat(5,1fr);gap:5px}.scale label{display:grid;place-items:center;height:38px;border:1px solid var(--line);background:#fff;border-radius:4px;font:600 12px var(--mono)}.scale input{position:absolute;opacity:0}.scale label:has(input:checked){border-color:var(--blue);background:var(--soft);color:var(--blue)}textarea{width:100%;min-height:72px;border:1px solid #bfc8d2;border-radius:4px;padding:9px;resize:vertical}.save{width:100%;margin-top:15px;border:1px solid #194b7c;border-radius:4px;background:var(--blue);color:#fff;padding:11px;font-weight:700}.error{display:none;color:var(--danger);font-size:12px;margin-top:10px}.complete{display:none;padding:60px;text-align:center}.complete h2{font:600 28px var(--record)}@media(max-width:820px){.head{align-items:flex-start;flex-direction:column}.desk{grid-template-columns:1fr}.record{border-right:0;border-bottom:1px solid var(--line)}main{padding:0 14px 40px}.head,.record,form{padding:20px}}
</style></head><body><header><div class="head"><div><h1>Reply quality review desk</h1><p>Rate the exact generated reply · judge scores hidden</p><a href="/">Switch to training-label review</a></div><div class="reviewer"><label for="reviewer">Reviewer ID</label><input id="reviewer" placeholder="reviewer-a"></div></div></header><main><div class="progress"><strong id="position">Enter a reviewer ID</strong><div class="track"><div id="fill" class="fill"></div></div><strong id="remaining">50 remaining</strong></div><section id="desk" class="desk"><article class="record"><div id="number" class="number">Reply —</div><h2>Judge the response shown, not the system that produced it.</h2><div class="message"><span class="label">Customer message</span><p id="customer">Enter your reviewer ID to begin.</p></div><div class="message reply"><span class="label">Generated reply</span><p id="reply">The exact benchmark draft appears here.</p></div><div><span class="label">Required resolution act</span><p id="act" class="act">—</p></div><p class="note">Groundedness means no unsupported promise or invented fact. Safety includes privacy, approved links, and respecting specialist transfer. Local judge scores are intentionally hidden.</p></article><form id="form"><div id="dimensions"></div><label class="label" for="notes">Optional notes</label><textarea id="notes"></textarea><div id="error" class="error"></div><button id="save" class="save" type="submit">Save ratings and open next reply</button></form></section><section id="complete" class="complete"><h2>Reply ratings complete</h2><p>Run aggregation after the second reviewer finishes.</p></section></main><script>
const fields={groundedness:"Supported by the case and evidence",empathy:"Professional and proportionate",actionability:"Clear, usable next step",safety:"Privacy and policy compliant"};const el=id=>document.getElementById(id);let item=null;const dimensions=el("dimensions");Object.entries(fields).forEach(([field,help])=>{const box=document.createElement("div");box.className="dimension";box.innerHTML=`<header><strong>${field[0].toUpperCase()+field.slice(1)}</strong><span>${help}</span></header><div class="scale">${[1,2,3,4,5].map(n=>`<label><input type="radio" name="${field}" value="${n}" required>${n}</label>`).join("")}</div>`;dimensions.append(box)});function error(e){el("error").textContent=e.message;el("error").style.display="block"}async function load(){const reviewer=el("reviewer").value.trim();if(!reviewer)return;const response=await fetch(`/api/ratings/next?reviewer_id=${encodeURIComponent(reviewer)}`);const data=await response.json();if(!response.ok)throw new Error(data.detail||"Could not load ratings");if(data.complete){el("desk").style.display="none";el("complete").style.display="block";el("fill").style.width="100%";return}item=data;el("form").reset();el("number").textContent=`Reply ${data.position} · ${data.reply_id}`;el("customer").textContent=data.customer_text;el("reply").textContent=data.draft_reply;el("act").textContent=data.resolution_act;el("position").textContent=`${data.completed} of ${data.total} rated`;el("remaining").textContent=`${data.remaining} remaining`;el("fill").style.width=`${100*data.completed/data.total}%`}el("reviewer").addEventListener("change",()=>load().catch(error));el("form").addEventListener("submit",async event=>{event.preventDefault();el("error").style.display="none";if(!item)return;const body={reviewer_id:el("reviewer").value.trim(),reply_id:item.reply_id,source_sha256:item.source_sha256,human_notes:el("notes").value};for(const field of Object.keys(fields)){const selected=document.querySelector(`input[name="${field}"]:checked`);if(!selected)return error(new Error("Rate all four dimensions"));body[`human_${field}`]=Number(selected.value)}el("save").disabled=true;try{const response=await fetch("/api/ratings",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});const data=await response.json();if(!response.ok)throw new Error(data.detail||"Ratings were not saved");await load()}catch(e){error(e)}finally{el("save").disabled=false}});
</script></body></html>"""
